cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g2-1/bot.mjs';

const user = (over = {}) => ({ id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3, ...over });
const at = (iso) => new Date(iso);
const r = (g, u, iso) => g.attempt(u, at(iso));
const deny = (reason) => ({ allowed: false, reason });
const ok = { allowed: true, reason: null };
const fails = [];
const check = (name, fn) => { try { fn(); console.log('ok   -', name); } catch (e) { fails.push(name); console.log('FAIL -', name, '\n', e.message); } };

// Tokyo is UTC+9, no DST.
check('quiet: 22:00 JST is quiet (start inclusive)', () =>
  assert.deepEqual(r(createPushGate(), user(), '2026-10-22T13:00:00Z'), deny('quiet_hours')));   // 22:00 JST
check('quiet: 21:59 JST is allowed', () =>
  assert.deepEqual(r(createPushGate(), user(), '2026-10-22T12:59:00Z'), ok));                    // 21:59 JST
check('quiet: 00:30 JST is quiet (after midnight)', () =>
  assert.deepEqual(r(createPushGate(), user(), '2026-10-22T15:30:00Z'), deny('quiet_hours')));   // 00:30 JST Oct 23
check('quiet: 06:59 JST is quiet', () =>
  assert.deepEqual(r(createPushGate(), user(), '2026-10-21T21:59:00Z'), deny('quiet_hours')));   // 06:59 JST Oct 22
check('quiet: 07:00 JST is allowed (end exclusive)', () =>
  assert.deepEqual(r(createPushGate(), user(), '2026-10-21T22:00:00Z'), ok));                    // 07:00 JST Oct 22

check('quiet: non-wrapping window 13:00-14:00 works', () => {
  const u = user({ quietStart: '13:00', quietEnd: '14:00' });
  assert.deepEqual(r(createPushGate(), u, '2026-10-22T04:30:00Z'), deny('quiet_hours')); // 13:30 JST
  assert.deepEqual(r(createPushGate(), u, '2026-10-22T05:00:00Z'), ok);                  // 14:00 JST
});
check('quiet: start === end means no quiet window', () => {
  const u = user({ quietStart: '08:00', quietEnd: '08:00' });
  assert.deepEqual(r(createPushGate(), u, '2026-10-21T23:30:00Z'), ok); // 08:30 JST
});

check('quiet uses user zone, not UTC: New York 22:30 EDT is quiet, same instant is 11:30 UTC-wise not quiet in UTC', () => {
  const ny = user({ timeZone: 'America/New_York' });
  // 2026-10-22 02:30Z = 22:30 EDT Oct 21 (EDT = UTC-4 before DST ends Nov 1)
  assert.deepEqual(r(createPushGate(), ny, '2026-10-22T02:30:00Z'), deny('quiet_hours'));
  // 2026-10-22 14:00Z = 10:00 EDT, allowed
  assert.deepEqual(r(createPushGate(), ny, '2026-10-22T14:00:00Z'), ok);
});

check('cap: "day" is the user local calendar day, not UTC', () => {
  // Tokyo cap 1. 23:00 JST Oct 22 = 14:00Z Oct 22. Then 01:00 JST Oct 23 = 16:00Z Oct 22.
  // Same UTC date, different local date, so the second push must be allowed.
  const g = createPushGate();
  const u = user({ dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' });
  assert.deepEqual(r(g, u, '2026-10-22T14:00:00Z'), ok);
  assert.deepEqual(r(g, u, '2026-10-22T16:00:00Z'), ok);
  assert.deepEqual(r(g, u, '2026-10-22T16:30:00Z'), deny('daily_cap_reached')); // 01:30 JST Oct 23, cap reached for that day
});
check('cap: reached within a local day blocks, rule order is quiet > cap > gap', () => {
  const g = createPushGate();
  const u = user({ dailyCap: 2, quietStart: '23:00', quietEnd: '06:00' });
  assert.deepEqual(r(g, u, '2026-10-22T00:00:00Z'), ok);           // 09:00 JST
  assert.deepEqual(r(g, u, '2026-10-22T04:00:00Z'), ok);           // 13:00 JST
  assert.deepEqual(r(g, u, '2026-10-22T08:00:00Z'), deny('daily_cap_reached')); // 17:00 JST
  assert.deepEqual(r(g, u, '2026-10-22T14:30:00Z'), deny('quiet_hours'));       // 23:30 JST, quiet beats cap
});
check('cap: next local day resets the count', () => {
  const g = createPushGate();
  const u = user({ dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' });
  assert.deepEqual(r(g, u, '2026-10-22T00:00:00Z'), ok);           // 09:00 JST Oct 22
  assert.deepEqual(r(g, u, '2026-10-22T03:00:00Z'), deny('daily_cap_reached')); // 12:00 JST Oct 22
  assert.deepEqual(r(g, u, '2026-10-22T15:30:00Z'), ok);           // 00:30 JST Oct 23
});
check('cap 0 blocks everything that is not quiet', () => {
  assert.deepEqual(r(createPushGate(), user({ dailyCap: 0 }), '2026-10-22T00:00:00Z'), deny('daily_cap_reached'));
});
check('blocked attempts do not count toward the cap', () => {
  const g = createPushGate();
  const u = user({ dailyCap: 1 });
  assert.deepEqual(r(g, u, '2026-10-22T13:30:00Z'), deny('quiet_hours')); // quiet, not recorded
  assert.deepEqual(r(g, u, '2026-10-22T00:00:00Z'), ok);                 // 09:00 JST, first real push
});

check('gap: pushes closer than 30 min are blocked, exactly 30 min is allowed', () => {
  const g = createPushGate();
  const u = user();
  assert.deepEqual(r(g, u, '2026-10-22T01:00:00Z'), ok);                       // 10:00 JST
  assert.deepEqual(r(g, u, '2026-10-22T01:10:00Z'), deny('too_soon_after_last_push'));
  assert.deepEqual(r(g, u, '2026-10-22T01:30:00Z'), ok);                       // exactly 30 min after the first
});
check('gap: same reason across cap and gap is still distinct when cap is hit first', () => {
  const g = createPushGate();
  const u = user({ dailyCap: 1 });
  assert.deepEqual(r(g, u, '2026-10-22T01:00:00Z'), ok);
  assert.deepEqual(r(g, u, '2026-10-22T01:05:00Z'), deny('daily_cap_reached'));
});

check('state: gates are independent', () => {
  const a = createPushGate(), b = createPushGate();
  assert.deepEqual(r(a, user({ dailyCap: 1 }), '2026-10-22T00:00:00Z'), ok);
  assert.deepEqual(r(b, user({ dailyCap: 1 }), '2026-10-22T00:00:00Z'), ok);
});
check('state: users are independent within one gate', () => {
  const g = createPushGate();
  assert.deepEqual(r(g, user({ id: 'a', dailyCap: 1 }), '2026-10-22T00:00:00Z'), ok);
  assert.deepEqual(r(g, user({ id: 'b', dailyCap: 1 }), '2026-10-22T00:05:00Z'), ok);
});
check('state: uses the settings passed in each call', () => {
  const g = createPushGate();
  assert.deepEqual(r(g, user({ dailyCap: 1 }), '2026-10-22T00:00:00Z'), ok);
  assert.deepEqual(r(g, user({ dailyCap: 5 }), '2026-10-22T02:00:00Z'), ok); // cap raised, now allowed
  assert.deepEqual(r(g, user({ dailyCap: 2, quietStart: '12:00', quietEnd: '13:00' }), '2026-10-22T03:30:00Z'), deny('quiet_hours')); // 12:30 JST
});
check('reasons are distinct snake_case codes', () => {
  assert.deepEqual(new Set(['quiet_hours', 'daily_cap_reached', 'too_soon_after_last_push']).size, 3);
});

check('input validation throws', () => {
  const g = createPushGate();
  const d = new Date('2026-10-22T00:00:00Z');
  assert.throws(() => g.attempt(user({ timeZone: 'Mars/Olympus' }), d), RangeError);
  assert.throws(() => g.attempt(user({ quietStart: '25:00' }), d), TypeError);
  assert.throws(() => g.attempt(user({ quietEnd: '7:00' }), d), TypeError);
  assert.throws(() => g.attempt(user({ dailyCap: -1 }), d), TypeError);
  assert.throws(() => g.attempt(user({ dailyCap: 1.5 }), d), TypeError);
  assert.throws(() => g.attempt(user({ id: '' }), d), TypeError);
  assert.throws(() => g.attempt(user(), new Date('nope')), TypeError);
  assert.throws(() => g.attempt(user(), 1700000000000), TypeError);
});

check('clock stepping backwards does not block for hours', () => {
  const g = createPushGate();
  const u = user({ dailyCap: 5 });
  assert.deepEqual(r(g, u, '2026-10-22T03:00:00Z'), ok);
  assert.deepEqual(r(g, u, '2026-10-22T01:00:00Z'), deny('too_soon_after_last_push')); // 2h back, within gap window of abs? no: 2h > 30m
});

console.log(fails.length ? `\n${fails.length} FAILED` : `\nall ${n} checks passed`);
process.exit(fails.length ? 1 : 0);
EOF
cd /tmp/bot-test && node test.mjs
